function updateAnnounceDates(){const dateElements=document.querySelectorAll('.announce-date');const today=new Date();const todayString=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');dateElements.forEach(el=>{const dateAttr=el.getAttribute('data-date');if(!dateAttr)return;if(dateAttr===todayString){el.textContent=translations[currentLang].todayLabel||(currentLang==='vi'?"Hôm nay":"Today")}else{const parts=dateAttr.split('-');if(parts.length===3){el.textContent=parts[2]+'/'+parts[1]+'/'+parts[0]}}})}
